/**
 * Becky Compiler
 *
 * Reads rules from core/rules/, agents from agents/, and wiki index from wiki/compiled/index.md.
 * Produces CLAUDE.md and AGENTS.md in the target project directory.
 *
 * Usage: npx tsx core/compile.ts [--target /path/to/project]
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { getInstallRoot } from "./paths.js";
import { parse as parseYaml } from "yaml";
// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const BECKY_ROOT = getInstallRoot();
function parseFrontmatter(raw) {
    const match = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
    if (!match)
        return { frontmatter: {}, body: raw };
    const frontmatter = parseYaml(match[1]);
    const body = match[2].trim();
    return { frontmatter, body };
}
function loadRules() {
    const rulesDir = join(BECKY_ROOT, "core", "rules");
    const files = readdirSync(rulesDir).filter((f) => f.endsWith(".md") && !f.startsWith("_"));
    return files.map((filename) => {
        const raw = readFileSync(join(rulesDir, filename), "utf-8");
        const { frontmatter, body } = parseFrontmatter(raw);
        return {
            frontmatter: frontmatter,
            body,
            filename,
        };
    });
}
function loadWikiIndex() {
    const indexPath = join(BECKY_ROOT, "wiki", "compiled", "index.md");
    if (!existsSync(indexPath))
        return "";
    return readFileSync(indexPath, "utf-8");
}
function loadConfig() {
    const configPath = join(BECKY_ROOT, "becky.config.yaml");
    if (!existsSync(configPath)) {
        return {
            project: { name: "Project", root: ".", output_folder: "_output" },
            compile: {
                claude_output: "CLAUDE.md",
                codex_output: "AGENTS.md",
                include_wiki_index: true,
                include_memory_refs: false,
            },
        };
    }
    const raw = readFileSync(configPath, "utf-8");
    return parseYaml(raw);
}
function rulesForScope(rules, scope) {
    return rules.filter((r) => {
        const s = r.frontmatter.scope || "all";
        return s === "all" || s.includes(scope);
    });
}
// ---------------------------------------------------------------------------
// Compile CLAUDE.md
// ---------------------------------------------------------------------------
function compileClaude(rules, wikiIndex, config) {
    const filtered = rulesForScope(rules, "claude");
    const sections = filtered.map((r) => {
        const severity = r.frontmatter.severity ? ` [${r.frontmatter.severity}]` : "";
        return `## ${r.frontmatter.title}${severity}\n\n${r.body}`;
    });
    let output = `# ${config.project.name} — Agent Instructions\n\n`;
    output += "*Generated by Becky. Do not edit — edit `core/rules/` and run `becky compile`.*\n\n";
    output += sections.join("\n\n---\n\n");
    if (config.compile.include_wiki_index && wikiIndex) {
        output += `\n\n---\n\n## Knowledge Base\n\n${wikiIndex}`;
    }
    return output;
}
// ---------------------------------------------------------------------------
// Compile AGENTS.md
// ---------------------------------------------------------------------------
function compileAgents(rules, wikiIndex, config) {
    const filtered = rulesForScope(rules, "codex");
    let output = `# ${config.project.name} — Agent Workspace\n\n`;
    output += "*Generated by Becky. Do not edit — edit `core/rules/` and run `becky compile`.*\n\n";
    output += `## Session Startup\n\n`;
    output += `1. Read this file — these are the rules you enforce.\n`;
    output += "2. Read the wiki index at `wiki/compiled/index.md` for project context.\n";
    output += "3. Read `memory/project/` for project-specific knowledge.\n\n";
    output += `## Rules\n\n`;
    for (const r of filtered) {
        const severity = r.frontmatter.severity ? ` [${r.frontmatter.severity}]` : "";
        output += `### ${r.frontmatter.id}: ${r.frontmatter.title}${severity}\n\n`;
        output += `${r.body}\n\n`;
    }
    output += `## Verification Standard\n\n`;
    output += `| Tier | Evidence |\n|------|----------|\n`;
    output += `| DONE | Runtime artifact (API response, DB query, screenshot) |\n`;
    output += `| VERIFIED | AC line-by-line with code citations |\n`;
    output += `| AUDITED | File exists, function names match |\n\n`;
    output += `Report tiers separately. Never upgrade a tier without evidence.\n`;
    if (config.compile.include_wiki_index && wikiIndex) {
        output += `\n---\n\n## Knowledge Base\n\n${wikiIndex}`;
    }
    return output;
}
// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
function main() {
    const args = process.argv.slice(2);
    const targetIdx = args.indexOf("--target");
    const targetDir = targetIdx >= 0 && args[targetIdx + 1]
        ? resolve(args[targetIdx + 1])
        : resolve(".");
    console.log(`Becky compile — reading rules from ${join(BECKY_ROOT, "core", "rules")}`);
    const config = loadConfig();
    const rules = loadRules();
    const wikiIndex = loadWikiIndex();
    console.log(`  Found ${rules.length} rules`);
    // Compile
    const claudeOutput = compileClaude(rules, wikiIndex, config);
    const agentsOutput = compileAgents(rules, wikiIndex, config);
    // Write
    const claudePath = join(targetDir, config.compile.claude_output);
    const agentsPath = join(targetDir, config.compile.codex_output);
    writeFileSync(claudePath, claudeOutput, "utf-8");
    console.log(`  Wrote ${claudePath} (${claudeOutput.length} chars)`);
    writeFileSync(agentsPath, agentsOutput, "utf-8");
    console.log(`  Wrote ${agentsPath} (${agentsOutput.length} chars)`);
    console.log(`Becky compile complete.`);
}
main();
